UPDATE alert_record
SET escalation_level = #{newLevel},
    last_escalated_at = #{escalatedAt,jdbcType=TIMESTAMP},
    assignee_id = COALESCE(#{assigneeId,jdbcType=BIGINT}, assignee_id),
    updated_at = #{escalatedAt,jdbcType=TIMESTAMP}
WHERE id = #{id}
  AND escalation_level = #{currentLevel}

UPDATE alert_record
SET assignee_id = #{assigneeId,jdbcType=BIGINT},
    updated_at = #{updatedAt,jdbcType=TIMESTAMP}
WHERE id = #{id}
  AND user_id = #{userId}
